<template><section class="aw-records"><header><div><p class="aw-eyebrow">{{ agency.name }}</p><h1>{{ titles[section] }}</h1></div><button @click="load" :disabled="loading">Refresh</button></header><form v-if="section === 'clients'" @submit.prevent="page=1;load()"><label>Find a client <input v-model="search" type="search" placeholder="Name or initials"></label><button>Search</button></form><p role="alert" v-if="error">{{ error }}</p><p v-else-if="loading" role="status">Loading {{ titles[section].toLowerCase() }}…</p><p v-else-if="!rows.length">No records found in this practice.</p><div v-else class="aw-table"><table><thead><tr><th>{{ section === 'appointments' ? 'Appointment' : 'Name' }}</th><th>{{ section === 'providers' ? 'Credential' : section === 'appointments' ? 'Service' : 'Status' }}</th><th>{{ section === 'providers' ? 'Status' : section === 'appointments' ? 'Status' : 'Documentation' }}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><button v-if="section === 'providers'" type="button" @click="selectedProvider = r">{{ [r.first_name,r.last_name].filter(Boolean).join(' ') }}</button><span v-else>{{ section === 'providers' ? [r.first_name,r.last_name].filter(Boolean).join(' ') : section === 'appointments' ? date(r.startAt || r.start_at) : r.full_name || r.initials || `Client #${r.id}` }}</span></td><td>{{ section === 'providers' ? r.credential || 'Not recorded' : section === 'appointments' ? r.serviceCode || r.service_code || 'Appointment' : r.status || '—' }}</td><td><RouterLink v-if="section === 'clients'" :to="{path:`/${slug}/clients`,query:{clientId:String(r.id)}}">Open chart →</RouterLink><span v-else>{{ section === 'providers' ? (r.is_active && !['ARCHIVED','INACTIVE_EMPLOYEE'].includes(r.status) ? 'Active' : 'Inactive · history') : r.status }}</span></td></tr></tbody></table></div><div v-if="section === 'clients'" class="aw-pagination"><button :disabled="loading || page === 1" @click="page--;load()">Previous</button><span>Page {{ page }}</span><button :disabled="loading || rows.length < 50" @click="page++;load()">Next</button></div><section v-if="selectedProvider && section === 'providers'" class="aw-provider-profile" aria-label="Provider profile"><img v-if="selectedProvider.profile_photo_url" :src="selectedProvider.profile_photo_url" alt=""><div><h2>{{ selectedProvider.first_name }} {{ selectedProvider.last_name }}</h2><p>{{ selectedProvider.credential || 'Credential not recorded' }}</p><p v-if="selectedProvider.bio">{{ selectedProvider.bio }}</p><dl><dt>Status</dt><dd>{{ selectedProvider.is_active && !['ARCHIVED','INACTIVE_EMPLOYEE'].includes(selectedProvider.status) ? 'Active' : 'Inactive · historical attribution' }}</dd><template v-if="selectedProvider.specialties?.length"><dt>Care focus</dt><dd>{{ selectedProvider.specialties.join(', ') }}</dd></template></dl></div><button type="button" @click="selectedProvider = null">Close profile</button></section><p v-if="section === 'providers'" class="aw-caption">Credentials are shown as recorded. This directory does not establish payer eligibility or enrollment.</p><p v-if="section === 'appointments'" class="aw-caption">Existing appointments for the next 30 days. Appointment changes remain in the full suite during preview.</p></section></template>
<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue';
import api from '../services/api';
const props = defineProps({section:String,agency:Object,slug:String});
const titles={clients:'Clients',providers:'Providers',appointments:'Appointments'};
const selectedProvider=ref(null);
const rows=ref([]),loading=ref(false),error=ref(''),search=ref(''),page=ref(1);let seq=0;
const date=v => v ? new Date(v).toLocaleString() : 'Time not recorded';
async function load(){const id=++seq;rows.value=[];loading.value=true;error.value='';try{const start=new Date(),end=new Date(Date.now()+30*86400000);const paths={clients:'/clients',providers:'/auricwell-preview/providers',appointments:'/appointments'};const {data}=await api.get(paths[props.section],{params:{agencyId:props.agency.id,agency_id:props.agency.id,...(props.section==='clients'?{search:search.value,page:page.value,per_page:50,paginate:1}:{}),...(props.section==='appointments'?{windowStart:start.toISOString().slice(0,10),windowEnd:end.toISOString().slice(0,10)}: {})}});if(id!==seq)return;rows.value=Array.isArray(data)?data:data.clients||data.providers||data.appointments||data.items||[];}catch(e){if(id===seq)error.value=e.response?.data?.error?.message||e.message;}finally{if(id===seq)loading.value=false;}}
onMounted(load);onBeforeUnmount(()=>++seq);
</script>
